CREATE TYPE public.edu_role AS ENUM ('teacher','director');
CREATE TABLE public.schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 160), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.schools TO authenticated;
GRANT ALL ON public.schools TO service_role;
ALTER TABLE public.schools ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name) <= 120));
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE(display_name) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, school_id uuid NOT NULL REFERENCES public.schools(id), role public.edu_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.edu_school() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT school_id FROM public.user_roles WHERE user_id=auth.uid() $$;
CREATE FUNCTION public.edu_has_role(wanted public.edu_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=wanted) $$;
REVOKE ALL ON FUNCTION public.edu_school(), public.edu_has_role(public.edu_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edu_school(), public.edu_has_role(public.edu_role) TO authenticated;
CREATE POLICY member_school_read ON public.schools FOR SELECT TO authenticated USING (id=public.edu_school());
CREATE FUNCTION public.edu_profile_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),120)); RETURN NEW; END $$;
CREATE TRIGGER edu_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.edu_profile_signup();
CREATE TABLE public.school_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES public.schools(id), email text NOT NULL CHECK(length(email)<=255), role public.edu_role NOT NULL, token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, used_at timestamptz, expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days'), created_by uuid NOT NULL);
GRANT SELECT ON public.school_invites TO authenticated;
GRANT ALL ON public.school_invites TO service_role;
ALTER TABLE public.school_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY director_invites_read ON public.school_invites FOR SELECT TO authenticated USING (school_id=public.edu_school() AND public.edu_has_role('director'));
CREATE FUNCTION public.edu_create_school(school_name text, chosen_role public.edu_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(school_name)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid school'; END IF; INSERT INTO public.schools(name,created_by) VALUES(trim(school_name),auth.uid()) RETURNING id INTO sid; INSERT INTO public.user_roles VALUES(auth.uid(),sid,chosen_role); RETURN sid; END $$;
CREATE FUNCTION public.edu_invite(invite_email text, invite_role public.edu_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tok uuid; BEGIN IF NOT public.edu_has_role('director') OR invite_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' OR length(invite_email)>255 THEN RAISE EXCEPTION 'Forbidden or invalid email'; END IF; INSERT INTO public.school_invites(school_id,email,role,created_by) VALUES(public.edu_school(),lower(trim(invite_email)),invite_role,auth.uid()) RETURNING token INTO tok; RETURN tok; END $$;
CREATE FUNCTION public.edu_join_school(invite_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.school_invites; verified_email text; BEGIN IF auth.uid() IS NULL OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT email INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; SELECT * INTO inv FROM public.school_invites WHERE token=invite_token AND used_at IS NULL AND expires_at>now() AND email=lower(verified_email) FOR UPDATE; IF inv.id IS NULL THEN RAISE EXCEPTION 'Invalid invitation'; END IF; INSERT INTO public.user_roles VALUES(auth.uid(),inv.school_id,inv.role); UPDATE public.school_invites SET used_at=now() WHERE id=inv.id; RETURN inv.school_id; END $$;
REVOKE ALL ON FUNCTION public.edu_create_school(text,public.edu_role), public.edu_invite(text,public.edu_role), public.edu_join_school(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edu_create_school(text,public.edu_role), public.edu_invite(text,public.edu_role), public.edu_join_school(uuid) TO authenticated;
CREATE TABLE public.students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES public.schools(id), teacher_id uuid NOT NULL REFERENCES public.profiles(id), code text NOT NULL CHECK(code ~ '^[A-Z0-9][A-Z0-9-]{2,31}$'), course text NOT NULL CHECK(length(trim(course)) BETWEEN 1 AND 80), attendance numeric NOT NULL CHECK(attendance BETWEEN 0 AND 100), submissions numeric NOT NULL CHECK(submissions BETWEEN 0 AND 100), resource_usage numeric NOT NULL CHECK(resource_usage BETWEEN 0 AND 100), grade numeric NOT NULL CHECK(grade BETWEEN 0 AND 10), observations text NOT NULL DEFAULT '' CHECK(length(observations)<=3000), enrollment_status text NOT NULL DEFAULT 'active' CHECK(enrollment_status IN ('active','completed','withdrawn')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,code));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.students TO authenticated;
GRANT ALL ON public.students TO service_role;
ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_students_read ON public.students FOR SELECT TO authenticated USING (school_id=public.edu_school() AND teacher_id=auth.uid() AND public.edu_has_role('teacher'));
CREATE POLICY teacher_students_insert ON public.students FOR INSERT TO authenticated WITH CHECK (school_id=public.edu_school() AND teacher_id=auth.uid() AND public.edu_has_role('teacher'));
CREATE POLICY teacher_students_update ON public.students FOR UPDATE TO authenticated USING (school_id=public.edu_school() AND teacher_id=auth.uid() AND public.edu_has_role('teacher')) WITH CHECK (school_id=public.edu_school() AND teacher_id=auth.uid() AND public.edu_has_role('teacher'));
CREATE POLICY teacher_students_delete ON public.students FOR DELETE TO authenticated USING (school_id=public.edu_school() AND teacher_id=auth.uid() AND public.edu_has_role('teacher'));
CREATE INDEX students_teacher_idx ON public.students(teacher_id);
CREATE INDEX students_school_idx ON public.students(school_id);
CREATE TABLE public.metric_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, attendance numeric NOT NULL, submissions numeric NOT NULL, resource_usage numeric NOT NULL, grade numeric NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.metric_history TO authenticated;
GRANT ALL ON public.metric_history TO service_role;
ALTER TABLE public.metric_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_history_read ON public.metric_history FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.students s WHERE s.id=student_id));
CREATE INDEX history_student_idx ON public.metric_history(student_id,recorded_at);
CREATE FUNCTION public.edu_track_metrics() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); IF TG_OP='INSERT' THEN INSERT INTO public.metric_history(student_id,attendance,submissions,resource_usage,grade) VALUES(NEW.id,NEW.attendance,NEW.submissions,NEW.resource_usage,NEW.grade); ELSIF (NEW.attendance,NEW.submissions,NEW.resource_usage,NEW.grade) IS DISTINCT FROM (OLD.attendance,OLD.submissions,OLD.resource_usage,OLD.grade) THEN INSERT INTO public.metric_history(student_id,attendance,submissions,resource_usage,grade) VALUES(NEW.id,NEW.attendance,NEW.submissions,NEW.resource_usage,NEW.grade); END IF; RETURN NEW; END $$;
CREATE TRIGGER track_student_metrics AFTER INSERT OR UPDATE ON public.students FOR EACH ROW EXECUTE FUNCTION public.edu_track_metrics();
CREATE TABLE public.intervention_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, school_id uuid NOT NULL REFERENCES public.schools(id), teacher_id uuid NOT NULL REFERENCES public.profiles(id), support_action text NOT NULL CHECK(support_action IN ('tutoring','resources','family','mentoring')), priority text NOT NULL CHECK(priority IN ('low','medium','high')), notes text NOT NULL CHECK(length(trim(notes)) BETWEEN 1 AND 3000), status text NOT NULL DEFAULT 'pendiente' CHECK(status IN ('pendiente','en_curso','completado')), reviewed boolean NOT NULL DEFAULT true CHECK(reviewed=true), reviewed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.intervention_plans TO authenticated;
GRANT ALL ON public.intervention_plans TO service_role;
ALTER TABLE public.intervention_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY teacher_plans_read ON public.intervention_plans FOR SELECT TO authenticated USING (teacher_id=auth.uid() AND school_id=public.edu_school() AND public.edu_has_role('teacher'));
CREATE POLICY teacher_plans_insert ON public.intervention_plans FOR INSERT TO authenticated WITH CHECK (teacher_id=auth.uid() AND school_id=public.edu_school() AND public.edu_has_role('teacher') AND EXISTS(SELECT 1 FROM public.students s WHERE s.id=student_id AND s.school_id=intervention_plans.school_id AND s.teacher_id=auth.uid()));
CREATE POLICY teacher_plans_update ON public.intervention_plans FOR UPDATE TO authenticated USING (teacher_id=auth.uid() AND school_id=public.edu_school() AND public.edu_has_role('teacher')) WITH CHECK (teacher_id=auth.uid() AND school_id=public.edu_school() AND public.edu_has_role('teacher') AND EXISTS(SELECT 1 FROM public.students s WHERE s.id=student_id AND s.school_id=intervention_plans.school_id AND s.teacher_id=auth.uid()));
CREATE POLICY teacher_plans_delete ON public.intervention_plans FOR DELETE TO authenticated USING (teacher_id=auth.uid() AND school_id=public.edu_school() AND public.edu_has_role('teacher'));
CREATE INDEX plans_student_idx ON public.intervention_plans(student_id);
CREATE FUNCTION public.edu_dashboard() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR public.edu_school() IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; WITH visible AS (SELECT * FROM public.students WHERE school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())), gs AS (SELECT course AS grupo,count(*) AS total,round(avg(attendance),1) AS asistencia,round(avg(grade),1) AS nota_media,round(avg(submissions),1) AS tareas_entregadas,round(avg(resource_usage),1) AS recursos FROM visible GROUP BY course), trend AS (SELECT to_char(h.recorded_at,'YYYY-MM-DD') AS day,round(avg(h.attendance),1) AS attendance,round(avg(h.grade),1) AS grade FROM public.metric_history h JOIN visible s ON s.id=h.student_id GROUP BY to_char(h.recorded_at,'YYYY-MM-DD') ORDER BY day DESC LIMIT 30), impact AS (SELECT CASE WHEN s.resource_usage>=50 THEN 'high' ELSE 'low' END AS usage,count(*) AS total,round(avg(s.attendance),1) AS attendance,round(avg(s.submissions),1) AS submissions,round(avg(s.grade),1) AS grade,round(avg(s.attendance-first_metric.attendance) FILTER (WHERE history_count.n>1),1) AS change FROM visible s JOIN LATERAL (SELECT attendance FROM public.metric_history WHERE student_id=s.id ORDER BY recorded_at,id LIMIT 1) first_metric ON true JOIN LATERAL (SELECT count(*) AS n FROM public.metric_history WHERE student_id=s.id) history_count ON true GROUP BY CASE WHEN s.resource_usage>=50 THEN 'high' ELSE 'low' END) SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE enrollment_status='active'),'withdrawn',count(*) FILTER(WHERE enrollment_status='withdrawn'),'completed',count(*) FILTER(WHERE enrollment_status='completed'),'retention',CASE WHEN count(*)>0 THEN round(100.0*count(*) FILTER(WHERE enrollment_status<>'withdrawn')/count(*),1) ELSE NULL END,'attendance',round(avg(attendance),1),'grade',round(avg(grade),1),'submissions',round(avg(submissions),1),'resources',round(avg(resource_usage),1),'priority',count(*) FILTER(WHERE attendance<75 OR grade<5 OR submissions<60),'plans',(SELECT count(*) FROM public.intervention_plans WHERE school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())),'completedPlans',(SELECT count(*) FROM public.intervention_plans WHERE status='completado' AND school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())),'groups',coalesce((SELECT jsonb_agg(gs) FROM gs),'[]'::jsonb),'trend',coalesce((SELECT jsonb_agg(trend ORDER BY day) FROM trend),'[]'::jsonb),'impact',coalesce((SELECT jsonb_agg(impact) FROM impact),'[]'::jsonb)) INTO result FROM visible; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.edu_dashboard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edu_dashboard() TO authenticated;
CREATE FUNCTION public.edu_notify_school() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE member_id uuid; sid uuid; BEGIN sid=CASE WHEN TG_OP='DELETE' THEN OLD.school_id ELSE NEW.school_id END; FOR member_id IN SELECT user_id FROM public.user_roles WHERE school_id=sid LOOP PERFORM realtime.send('{}'::jsonb,'changed','edupulse:'||member_id::text,true); END LOOP; RETURN NULL; END $$;
CREATE TRIGGER notify_student_change AFTER INSERT OR UPDATE OR DELETE ON public.students FOR EACH ROW EXECUTE FUNCTION public.edu_notify_school();
CREATE TRIGGER notify_plan_change AFTER INSERT OR UPDATE OR DELETE ON public.intervention_plans FOR EACH ROW EXECUTE FUNCTION public.edu_notify_school();
CREATE POLICY edu_private_notifications ON realtime.messages FOR SELECT TO authenticated USING (realtime.topic()='edupulse:'||auth.uid()::text);
REVOKE ALL ON FUNCTION public.edu_profile_signup(), public.edu_track_metrics(), public.edu_notify_school() FROM PUBLIC;